def process(amherstPrecip, chathamPrecip, ashburnhamPrecip, bostonPrecip) -> pd.DataFrame:
    import pandas as pd
    import numpy as np

    def to_float(x):
        if pd.isna(x):
            return np.nan
        s = str(x).strip()
        if s in {'M', 'm', ''}:
            return np.nan
        # some rows like "1.01 2004" in Min/Max rows
        try:
            return float(s.split()[0])
        except Exception:
            return np.nan

    def summer_total_wide(df: pd.DataFrame) -> float:
        d = df.copy()
        d.columns = [str(c).strip() for c in d.columns]
        # drop summary rows like Max/Min at bottom; keep rows where Year is a 4-digit year
        d['YearNum'] = pd.to_numeric(d['Year'], errors='coerce')
        d = d[d['YearNum'].notna()]
        d = d[d['YearNum'].between(1900, 2100)]

        row2015 = d.loc[d['YearNum'] == 2015]
        if row2015.empty:
            return np.nan

        for m in ['Jun', 'Jul', 'Aug']:
            if m not in row2015.columns:
                raise ValueError(f'Missing expected month column {m} in precipitation file. Columns={list(row2015.columns)}')

        vals = [to_float(row2015.iloc[0][m]) for m in ['Jun', 'Jul', 'Aug']]
        return float(np.nansum(vals))

    city_totals = [
        {'city': 'Amherst', 'summerRainfall': summer_total_wide(amherstPrecip)},
        {'city': 'Chatham', 'summerRainfall': summer_total_wide(chathamPrecip)},
        {'city': 'Ashburnham', 'summerRainfall': summer_total_wide(ashburnhamPrecip)},
        {'city': 'Boston', 'summerRainfall': summer_total_wide(bostonPrecip)},
    ]
    out = pd.DataFrame(city_totals)
    out = out.sort_values(['summerRainfall', 'city'], ascending=[True, True]).reset_index(drop=True)
    return out

